What is the value for each of the following variables?
\{
bool a = ('a' < 'a');
bool b = ('b' > 'a');
bool c = (a * 4) \&\& b;
bool d = !(b || (c || true));
bool e = a \&\& b \&\& c \&\& d;
bool f = a || b || c || d;
